/// Every refusal `avra check` speaks of the package embedding `path`.
fn embed_refusals(path: string) -> List<string> {
    match avra_ran(["check", embedding_on_disk(path)]) {
        .Ok(o) -> [l for l in o.out.stdout.split("\n") if l.starts_with("error[")],
        .Err(_) -> ["the check did not run"],
    }
}

/// Every refusal `avra check` speaks of the package providing `path` (from its root) to a kind.
fn octets_refusals(path: string) -> List<string> {
    let pkg = "${embed_root()}/pkg"
    let _ = write_text(
        "${pkg}/src/main.av",
        "use @std.meta.{provided, Provider}\ntype K = { n: int }\nimpl Provider for K {\n    static fn provide(path: string, octets: Bytes, digest: string) -> K? { K { n: octets.length } }\n}\nconst A: K = provided<K>(\"${path}\")\nA.n\n",
    )
