            .MapSetMaybe -> self.map_set_maybe_val(vals),
            .EnumBoxed -> if self.whole(vals[0]) < 0 { Val.N } else { self.fresh_array([vals[0], vals[1]]) },
            .EnumTag -> self.enum_part_val(vals, 0, -1),
