//! A quote lowers as ONE `template` call: this file by its name, the quote's
//! offset, its runs, and its fills — each fill coerced by its seat's
//! kind through a `@std/meta` row — wrapped as the kind the body
//! parsed as. No new instruction.
use core.{
    code_handles,
    ExprId,
    SyntaxArena,
    Reg,
    DeclId,
    PatId,
    TypeId,
    Type,
    HoleKind,
    MetaKind,
    FillClass,
    Shape,
    Open,
    Slot,
