gen() { python3 $S/cgen.py $d $1 $S/ins_body.txt; sed -n '/^type Pin/,/^}/p' packages/std-relation/src/tests/stored_codec_wide_test.av | sed "s/\bPin\b/Pin$1/g; s/\bPair\b/Pair$1/g; s/enum Wide/enum Wide$1/" >> $d/src/p.av; }
