/// index every per-file read of a record goes through, so no site scans the record whole.
fn fields_by_file(fields: List<List<string>>) -> Map<string, List<List<string>>> {
    mut buckets: Map<string, Cell<List<List<string>>>> = {}
    for p in fields {
        let path? = line_file(p) else { continue }
        let own = buckets.get(path) ?? {
            let fresh: Cell<List<List<string>>> = list_cell()
            buckets.set(path, fresh)
            fresh
        }
        own.push(p)
    }
    mut out: Map<string, List<List<string>>> = {}
    for path, own in buckets { out.set(path, own.get()) }
