use @std.meta.{Type, Directive, Code, Kind, name, literal, list_of}
use @std.validate.{Decode, Value, Entry}

export trait Fields {
    static fn derive(t: Type) -> List<Directive> {
        let entries = list_of(
            [quote {
            Entry { key: ${literal(f.name)}, value: ${written(f.kind, name(f.name))} }
        } for f in t.fields],
        )
        Decode.supplied(t, quote { Value.Map(${entries}) })
    }
}

fn written(k: Kind, v: Code) -> Code {
    let text = match k {
        .Str or .Opt(.Str) -> quote { Value.Text(value) },
        rest -> quote { unsupported_test_projection() },
    }
    quote {
        match ${v} {
            value? -> ${text}
            null -> Value.Null
        }
    }
}
fields.av
    StableHasher,
    Writer,
    Reader,
    CodecFault,
    tagged,
}

export trait RelationRow {
    static fn derive(t: Type) -> List<Directive> {
        [beside(t, generated(t))]
    }

    /// The field marks this derive reads.
    static fn marks(t: Type) -> List<string> { relation_marks }
}

/// `@derive(Columns)` — a record carried as a relation's nested column,
/// hashed and written field by field. It generates nothing: it claims
/// the marks a stored type's fields read.
export trait Columns {
    static fn derive(_t: Type) -> List<Directive> { [] }
