            .Fp -> "fp",
            .Unit -> "unit",
            .Obj -> "obj",
            .Bin -> "bin",
            .Proof -> "proof",
            .Warn -> "warn",
            .Answer -> "answer",
            .Rows -> "rows",
            .History -> "history",
        }
    }

