            .Sig or .Fp or .Unit or .Warn or .Rows or .Answer or .History -> false,
        }
    }

    /// Whether a write of this family trims its kept files to the ceiling at once: a whole program
    /// is what a session of edits would fill a disk with.
    fn trimmed_on_write() -> bool {
        match self {
            .Bin -> true,
            .Sig or .Fp or .Unit or .Obj or .Proof or .Warn or .Answer or .Rows or .History -> false,
        }
    }

    /// Whether this family is one checkout's own, kept in the tree's store and never the machine's.
    fn checkout_own() -> bool {
        match self {
            .History -> true,
            .Sig or .Fp or .Unit or .Obj or .Bin or .Proof or .Warn or .Answer or .Rows -> false,
        }
    }
}

