}

/// A workspace lets go of the pack it held; the last one lets the pack go, its mappings and open
/// files with it.
export fn pack_released(at: string) {
    let left = (holders().get().get(at) ?? 0) - 1
    holders().put(at, if left > 0 { left } else { 0 })
    if left > 0 { return }
    for p in packs().get().get(at) ?? [] { pack_unmapped(p) }
    packs().put(at, [])
}

