/// The mark a print's root bears for the last process that used it: written once a process.
const USED: string = "used"

fn used_now(root: string) {
    let _ = make_dirs(root)
    let _ = write_text(joined_path(root, USED), "")
}

/// How long the machine keeps a compiler nobody runs: `AVRA_PRINTS_MAX_AGE_DAYS`, else two weeks.
const PRINTS_DAYS_KEPT: int = 14

/// THE MACHINE LETS A COMPILER GO when no process has used it for its days: its root, every
/// row and body under it, gone whole. Answers how many it let go.
export fn prints_collected() -> int {
    let shared? = machine_cache() else { return 0 }
    // LICENSED input.debug_flag: the machine store's own age limit, never an input of what is built
    let days = parse_int(env("AVRA_PRINTS_MAX_AGE_DAYS") ?? "") ?? PRINTS_DAYS_KEPT
    if days <= 0 { return 0 }
    let at = joined_path(shared, PRINTS)
    // LICENSED input.store_io: the machine's print roots, listed to let the unused go
    let roots = match list_dir(at) { .Ok(ns) -> ns, .Err(_) -> [] }
    let gone = [r for r in roots if unused_for(joined_path(at, r), days)]
    for r in gone { removed_whole(joined_path(at, r)) }
    gone.length
}

/// Whether no process has marked a print's root used for `days`.
fn unused_for(root: string, days: int) -> bool {
    let marked? = kept_file(joined_path(root, USED)) else { return true }
    // LICENSED input.store_clock: the age limit reads the wall clock, never an input of what is built
    wall_secs() - marked.at > days * 86400
}

/// One compiler print's root, what it holds and when a process last used it.
type PrintRoot = { path: string, bytes: int, at: int }

/// THE MACHINE KEEPS WITHIN ITS CEILING: the compiler prints go whole, the least recently used
/// first, until what they hold fits `budget`; the print in use stands. Answers how many went.
export fn trimmed_prints(shared: string, spare: string, budget: int) -> int {
    let at = joined_path(shared, PRINTS)
    // LICENSED input.store_io: the machine's print roots, listed and measured to bound them
    let directory? = machine_store_dir() else { return null }
    let print? = own_print() else { return null }
    if !machine_store_stands(directory) { return null }
    std_answers_laid(directory, print)
    MachineLayer { directory: directory, print: print }
}

