//! THE SHARED CONTENT STORE (§6.1, DB 11): a value too big for a store's own frames
//! lives ONCE, under its content digest, beside every worktree's store, and a row
//! holds a REFERENCE to it. `AVRA_CACHE_DIR` moves the root, else `$HOME/.avra/cache`.
//!
//! A blob is a cache entry like any row: damaged or missing, it answers ABSENT, the
//! damaged one is removed, and the next writer puts it back. Each store root that
//! holds a reference registers itself, so `avra cache gc` knows every live reader.
//!
//! IT NEVER OUTGROWS ITS CEILING: a process that put a blob trims the store as it settles,
//! the least recently read first, to `AVRA_CAS_MAX_MB` (two gigabytes by default). A read
//! marks its blob's time, so the time a blob carries is when it was last of use.
use @std.io.{
    env,
    touch,
    make_dirs,
    write_bytes,
    write_text,
    read_text,
    list_dir,
    remove,
    open_beneath,
    exists,
}
use @std.path.{joined_path, dir_of}
use @std.text.{from_codepoint, parse_int}
use @std.time.{wall_secs}
use core.{digest_of_octets, sorted_by, distinct}
use core.debug.{qtrace, traced}

/// A value over this many octets is shared; the rest stay in the store's frames.
const CAS_CUT: int = 65536

/// What a shared store may hold, in megabytes, when `AVRA_CAS_MAX_MB` says nothing.
const CAS_MB_KEPT: int = 2048

/// A stored value that NAMES a blob, never a value: it opens with a control byte no row
/// value starts with, and a value that does is spelled as a reference too, so no value
/// can read as one by accident.
once fn cas_prefix() -> string { from_codepoint(1) + "avra-cas:" }

/// THE MACHINE'S CACHE: `AVRA_CACHE_DIR`, else `$HOME/.avra/cache` — where every worktree's
/// shared rows and blobs stand.
export fn machine_cache() -> string? {
    // LICENSED input.debug_flag: where the shared store lives is the machine's, never an input of what is built
    let moved? = env("AVRA_CACHE_DIR") else {
        // LICENSED input.debug_flag: where the shared store lives is the machine's, never an input of what is built
        let home? = env("HOME") else { return null }
        return joined_path(home, ".avra/cache")
    }
    moved
}

/// The machine cache this process keeps blobs in: none until a host that is a machine names
/// one, so a process of in-memory hosts writes no blob.
once fn machine_in_use() -> Cell<string> { Cell.new("") }

/// The process keeps its blobs in the machine cache at `dir` from now on.
export fn blobs_kept_in(dir: string) { machine_in_use().set(dir) }

/// Where the shared blobs stand.
fn cas_dir() -> string? {
    let dir = machine_in_use().get()
    if dir.is_empty() { return null }
    joined_path(dir, "cas")
}

fn blob_at(dir: string, digest: string) -> string { joined_path(joined_path(dir, digest.substring(0, 2)), digest) }

/// The digest a reference names.
export fn cas_digest_of(stored: string) -> string { stored.substring(cas_prefix().length, stored.length) }

/// The reference to a value's blob, minted from its content alone: the same value is the
/// same reference wherever it is written.
export fn cas_ref_of(value: string) -> string { cas_ref_octets(value.bytes()) }

/// `cas_ref_of` over octets.
fn cas_ref_octets(value: Bytes) -> string { cas_prefix() + digest_of_octets(value) }

/// Whether a value belongs in the shared store rather than a store's own frames.
export fn cas_big(value: string) -> bool { value.bytes().length > CAS_CUT }
