/// Whether the machine's store at `directory` stands for this process: made where it isn't, said
/// once where it can't be.
fn machine_store_stands(directory: string) -> bool {
    match make_dirs(directory) {
        .Ok(_) -> true,
        .Err(e) -> {
            said_once(store_unusable(directory, e))
            false
        },
    }
}

/// The toolchain's std answers for the binary printed `print`, laid into the machine's store at
/// `directory` once: each pack it ships that the store lacks, then the mark that they were.
fn std_answers_laid(directory: string, print: string) {
    let mark = joined_path(directory, "std-answers-${print}")
    if exists(mark) { return }
    let shipped? = shipped_answers() else { return }
    let packs = [n for n in list_dir(shipped) catch [] if pack_answers(unpacked_name(n), print)]
    if packs.is_empty() { return }
    for name in packs {
        match pack_laid(joined_path(shipped, name), joined_path(directory, unpacked_name(name))) {
            .Ok(_) -> {},
            .Err(why) -> {
                said_once(answers_unlaid(directory, why))
                return
            },
        }
    }
    let _ = file_laid(mark, "".bytes())
}

/// A shipped pack's name as the store names it: the name it was packed from.
fn unpacked_name(name: string) -> string {
    let format? = packed_as(name) else { return name }
    name.substring(0, name.length - format.suffix.length)
}

/// How a shipped pack was packed, by its name's suffix: absent for a pack shipped as it lies.
fn packed_as(name: string) -> Packing? { PACKINGS.find((p) -> name.ends_with(p.suffix)) }

/// One way a pack ships: the suffix its file wears, and the format it is encoded in.
type Packing = { suffix: string, format: Format }

/// The ways a pack ships packed.
const PACKINGS: List<Packing> = [SHIPPED_PACKING]

/// How a toolchain packs the answers it ships.
