/// How often a pack's records repeat what they read: every read, and every distinct read — a whole
/// read a question and the answer it saw, a part read those and the part it looked at.
export type ReadsRepeated = { whole: int, whole_distinct: int, part: int, part_distinct: int }

/// How often the records of the pack `name` of `directory` repeat what they read; absent for a pack
/// that doesn't stand whole.
export fn pack_reads_repeated(directory: string, name: string) -> ReadsRepeated? {
    let pack? = mapped_pack("${directory}/${name}") else { return null }
    let wholes: HashKeyedTable<bool> = hash_keyed_table()
    let parts: HashKeyedTable<bool> = hash_keyed_table()
    mut whole = 0
    mut part = 0
    for span in pack.question_spans(null) {
        for r in pack.records_of(span.key) {
            let _ = r.every_read(
                (q, seen) -> {
                    whole = whole + 1
                    wholes.put_at(q.high_word ^ seen.high_word.wrapping_mul(31), q.low_word ^ seen.low_word, true)
                    true
                },
                (q, seen, name, hash) -> {
                    part = part + 1
                    parts.put_at(q.high_word ^ name.high_word.wrapping_mul(31), q.low_word ^ seen.low_word ^ hash.low_word, true)
                    true
                },
            )
        }
    }
    ReadsRepeated { whole: whole, whole_distinct: wholes.values().length, part: part, part_distinct: parts.values().length }
}

