/// A source's stale citations among `remarks`, each as its file, line and id.
fn stale_lines_of(src: SourceFile, remarks: List<Remark>, known: List<string>) -> List<string> {
    ["${src.file}\t${c.line}\t${c.id}" for c in citations_naming_nothing(src, remarks, known)]
