/// THE STORE AS A DEPENDENT READS IT: every pack as one, keeping what every question reaches but
/// those of a query `roots` names, so what only a root reads goes and what anything else reads
/// stays.
fn compacted_without(roots: List<string>) -> Result<int, IoError> {
    let packs = self.packs.get()
    let segment? = self.writing() else { return .Ok(0) }
    let all = [span.key for pack in packs for span in pack.question_spans(null)]
    let rooted = [q for q in all if roots.contains(self.question_known_as(q)?.query_name ?? "")]
    let dropped = live_over(packs, segment, rooted)
    self.published(packs, true, [q for q in all if dropped.questions.get(q) == null])
}

