/// A command over the argued program — every command's one prologue:
/// no such file exits 2.
fn on_program(args: CliResult, act: fn(Program) -> int) -> int {
    let held? = program_at(args) else { return 2 }
    act(held)
}

/// A clean program's warnings, to stderr — never silent, never
/// blocking.
fn warn(p: Program) {
    let text = p.warnings()
    if text != "" { eprintln(text) }
}

/// The `--time` report: analysis by phase, then what the command
/// itself did, then the memo's hits and misses.
/// The phases, each name once with its times summed — a phase the
    path: string,
    scope: List<string>,
    made: List<BuildOutcome>,
    tools: Toolchain,
) -> int {
    for b in made {
        if !b.warnings.is_empty() { eprintln(b.warnings) }
        if timed(args) { eprintln(if b.reused { "time: suite · cache hit" } else { "time: ${b.phases}" }) }
    }
    if made.is_empty() { return nothing_to_prove(path, scope) }
    let refuses = flatten([b.refuses for b in made])
    if !refuses.is_empty() {
        let wrong = checked_refuses(own_binary(), tools, refuses)
        if wrong != 0 { return wrong }
    }
    handed_off([b.binary for b in made])
