// DESIGN GAP, NOT A SOUNDNESS BUG: this ticket's OWN doc comments
// name three motivating uses for the general Suggestion channel — a
// spell-check, a dependency line, a named type's wrap. All three of
// the compiler's REAL diagnostics of those shapes
// (`resolve.unresolved`'s "did you mean", `resolve.not_a_dependency`,
// `type.mismatch`'s named-type wrap) are built on `refusal`, which is
// Severity.Error by construction (diagnostics/mod.av's `error_at`).
// `packages/cli/src/commands/fix.av`'s `fixed` bails at its very
// first line, `if !p.clean() { fail p.report() }`, before it ever
// calls `suggestion_applications` — and `p.clean()` is false
// whenever ANY file in the program carries an error, which the
// diagnostic CARRYING the suggestion always does, by definition. So
// none of the three motivating examples can ever reach `avra fix`'s
// real CLI command; only a WARNING-severity source (a rule's own
// finding, or some future non-error diagnostic) can. Confirmed
// end-to-end against the real CLI binary, not just here: `avra fix`
// on a file with an unresolved-name typo prints the bare error
// report and exits 1, the same as `avra check` would — it never
// reaches the `[]`-or-populated JSON array `--json` prints once
// `suggestion_applications` runs.
spec "the general Suggestion channel's own motivating diagnostics are unreachable" {
    given "a real unresolved-name diagnostic, complete with its own \"did you mean\" Suggestion" {
        then "the program carrying it is NOT clean — avra fix's own gate bails before suggestion_applications ever runs" {
            mut ws = fix_ws_of("let value = 1\nvaleu\n")
            mut p: Program = ws.program("/w/src/main.av")
            let a = p.entry_file()!
            let sg_count = a.diagnostics.find(it.kind == "resolve.unresolved")?.suggestions?.length ?? 0
            !p.clean() && sg_count > 0
        }
    }
}

// THE COUNTEREXAMPLE: `type.coalesce_never` is a real WARNING (never
// blocks `p.clean()`) built far from any rule's Candidate, carrying a
// real Suggestion over `a.diagnostics` — the first non-rule diagnostic
// to actually reach `avra fix`'s apply path end to end, not merely a
// forward-looking one.
spec "a real WARNING-severity Suggestion reaching avra fix's own apply path" {
    given "`n ?? 4` where `n`'s type says it is never absent" {
        then "the program stays clean, and its own Suggestion PROVES and applies through the general channel" {
            let text = "fn f() -> int {\n    let n = 3\n    n ?? 4\n}\n0\n"
            mut ws = fix_ws_of(text)
            mut p: Program = ws.program("/w/src/main.av")
            let a = p.entry_file()!
            let apps = p.suggestion_applications("/w/src/main.av", analysed(a), a.diagnostics, null)
            p.clean() &&
                apps.length == 1 &&
                apps[0].kind == "type.coalesce_never" &&
                apps[0].proved &&
                fix_applied(text, apps) == "fn f() -> int {\n    let n = 3\n    n\n}\n0\n"
        }
    }
}

fn overlapping_apps() -> List<Application> {
    [
        then "a low-confidence assertion is never offered to the repair door" {
            repair_apps_of("fn f(n: int) -> int { n }\nlet v: int? = null\nf(v)\n").is_empty()
